import{_ as o,C as e,c as r,o as c,aa as l,G as t}from"./chunks/framework.ByRpVre_.js";const n="/assets/code-strings.BGeI04Et.png",p="/assets/menu.DG2322jB.png",h="/assets/before-modification.guLvzatz.png",f="/assets/after-modificationn.Clx-37aP.png",d="/assets/code-after-modification.BDmR7n_O.png",R=JSON.parse('{"title":"利用 Recaf 修改字节码进行内核汉化","description":"","frontmatter":{"breadcrumbs":[{"title":"Continue Project","link":"/guide"},{"title":"self-help","link":""},{"title":"利用 Recaf 修改字节码进行内核汉化","link":"/guide/self-help/localize-jars-with-recaf"}]},"headers":[],"relativePath":"guide/self-help/localize-jars-with-recaf.md","filePath":"guide/self-help/localize-jars-with-recaf.md"}'),u={name:"guide/self-help/localize-jars-with-recaf.md"};function b(g,a,_,m,k,x){const i=e("NolebaseGitContributors"),s=e("NolebaseGitChangelog");return c(),r("div",null,[a[0]||(a[0]=l(`<h1 id="利用-recaf-修改字节码进行内核汉化" tabindex="-1">利用 Recaf 修改字节码进行内核汉化 <a class="header-anchor" href="#利用-recaf-修改字节码进行内核汉化" aria-label="Permalink to &quot;利用 Recaf 修改字节码进行内核汉化&quot;">​</a></h1><p>Recaf 是一款现代化的开源 Java 字节码编辑器。它支持多种反编译方式，拥有相对较高的性能，在开发者界广受推崇。本文将会简要介绍软件的使用方法，并教授如何利用 Recaf 修改字符串达到汉化代码的目的。</p><div class="info custom-block"><p class="custom-block-title">阅前注意</p><p>本章节使用到的工具（Recaf-gui）可以从这里下载：<br><a href="https://github.com/Col-E/Recaf-Launcher/releases" target="_blank" rel="noreferrer">https://github.com/Col-E/Recaf-Launcher/releases</a></p></div><h2 id="_01-打开编辑器" tabindex="-1">01. 打开编辑器 <a class="header-anchor" href="#_01-打开编辑器" aria-label="Permalink to &quot;01. 打开编辑器&quot;">​</a></h2><p>Recaf 是以 jar 的形式分发的，它像 Minecraft 的开服核心一样，既可以直接点击打开，又可以通过 bat 脚本启动。</p><p>在 jar 文件旁边新建一个 bat 文件，并将如下内容放入：</p><div class="language-batch vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">batch</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">@echo</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> off</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">java -jar recaf-2.21.14-J8-jar-with-dependencies.jar</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">pause</span></span></code></pre></div><div class="info custom-block"><p class="custom-block-title">信息</p><p>实际指向的 jar 名称会因下载途径或版本不同而产生变化，请在放入运行前自行修改。</p></div><h2 id="_01-定位字符串" tabindex="-1">01. 定位字符串 <a class="header-anchor" href="#_01-定位字符串" aria-label="Permalink to &quot;01. 定位字符串&quot;">​</a></h2><p>首先需要准备好待汉化的插件或模组。</p><p>将 jar 文件拖入左侧空栏，或点击左上角“文件”，再点击“加载”，选择你需要的文件。</p><p>打开文件后，鼠标点击展开类，双击打开类文件，右侧会显示出反编译得到的插件代码。以 AdvancedCrates 为例，打开 Recaf 后，定位到需要汉化的字符串位置。</p><div class="info custom-block"><p class="custom-block-title">信息</p><p>字符串通常以英文单引号（<code>&#39;</code>）或双引号（<code>&quot;</code>）包裹，且 Recaf 自带的编辑器会以淡蓝色将其高亮标出。</p></div><div class="info custom-block"><p class="custom-block-title">信息</p><p>如果你的编辑器是英文，请参考本文最后的<a href="#01-切换-recaf-的显示语言">后记</a>部分找到解决方案。</p></div><figure><img src="`+n+'" alt="" tabindex="0"><figcaption>注意到图中有许多的字符串，记住它们。</figcaption></figure><h2 id="_02-打开表编辑模式" tabindex="-1">02. 打开表编辑模式 <a class="header-anchor" href="#_02-打开表编辑模式" aria-label="Permalink to &quot;02. 打开表编辑模式&quot;">​</a></h2><p>在选项卡上右键点击类名，点击“类查看方式”，将其切换为“Table”。</p><figure><img src="'+p+'" alt="" tabindex="0"><figcaption></figcaption></figure><h2 id="_03-找到方法名" tabindex="-1">03. 找到方法名 <a class="header-anchor" href="#_03-找到方法名" aria-label="Permalink to &quot;03. 找到方法名&quot;">​</a></h2><p>切换后，点击二级选项卡右侧的“方法”，你会看到一些表格。</p><p>根据上图，我们需要找的内容就藏在这里。右键第二个类，点击“编辑汇编代码”，程序会弹出一个新的窗口供你编辑。</p><p>这里的代码有点类似 Minecraft 中的指令。我们要做的，就是找到与之前看见过的字符串相同格式的代码，并定位它。</p><p>如果你没能找到你需要汉化的字符串，你可以按 Ctrl+F 唤起搜索框，将需要翻译的文本粘贴至此。</p><p>如果搜遍整块汇编代码都没有找到，那有可能是因为你没有找对地方。请回到表格的其他类里再次重复上述步骤并唤起搜索。</p><p>如果成功找到了字符串，就将其替换为中文，并记得保存。改动后的字符串会实时显示在代码中。<br> 修改字节码的一大优势就在于，它不需要引入外部库文件，便可以直接修改字符串。</p><figure><img src="'+h+'" alt="" tabindex="0"><figcaption>修改前的汇编代码</figcaption></figure><figure><img src="'+f+'" alt="" tabindex="0"><figcaption>修改后的汇编代码</figcaption></figure><figure><img src="'+d+'" alt="" tabindex="0"><figcaption>修改后的反编译代码</figcaption></figure><div class="warning custom-block"><p class="custom-block-title">警告</p><p>记得随时保存你的改动！出于某些原因，Recaf 并不能像大多数编辑器一样快速保存你的改动，也就是说，如果你在极短的时间之内先改动了字符串并按下了 Ctrl+S 保存，那么你的这些改用很有可能不会被记入。</p><p>因此，如果要防止这种情况出现，最好多按几下 Ctrl+S。Recaf 每次保存代码后，窗口边框都会闪烁提醒。</p></div><h2 id="_04-导出" tabindex="-1">04. 导出 <a class="header-anchor" href="#_04-导出" aria-label="Permalink to &quot;04. 导出&quot;">​</a></h2><p>回到程序主界面，点击左上角菜单的“文件”，选择“导出程序”，为文件命名好后保存即可。</p><h2 id="ex-后记" tabindex="-1">ex. 后记 <a class="header-anchor" href="#ex-后记" aria-label="Permalink to &quot;ex. 后记&quot;">​</a></h2><h3 id="_01-切换-recaf-的显示语言" tabindex="-1">01. 切换 Recaf 的显示语言 <a class="header-anchor" href="#_01-切换-recaf-的显示语言" aria-label="Permalink to &quot;01. 切换 Recaf 的显示语言&quot;">​</a></h3><p>Recaf 一开始可能是英语状态。</p><p>点击上方工具栏的“配置（Config）”，在里面找到“语言（Language）”一项，在展开式列表中找到 <code>zh-cn</code>（简体中文），关闭 Recaf 重启后即可将界面改为中文。</p><h3 id="_02-修改-recaf-显示字体" tabindex="-1">02. 修改 Recaf 显示字体 <a class="header-anchor" href="#_02-修改-recaf-显示字体" aria-label="Permalink to &quot;02. 修改 Recaf 显示字体&quot;">​</a></h3><p>Recaf 一开始的字体并不是非常令人满意。如果你需要修改字体，点击上方工具栏的“配置”，再找到“UI 字体”与“等宽文本（如编辑器）字体”这两项，在右侧的展开式列表中选择你需要的字体即可。个人推荐 <a href="https://font.subf.dev/zh-cn/download/" target="_blank" rel="noreferrer">Maple Mono NF CN</a>。</p><h3 id="_03-为什么不直接修改代码" tabindex="-1">03. 为什么不直接修改代码 <a class="header-anchor" href="#_03-为什么不直接修改代码" aria-label="Permalink to &quot;03. 为什么不直接修改代码&quot;">​</a></h3><p>很简单，如果你能找到导入代码中所需的库，那么这种直观快捷的修改方式是最合适的。然而，对于 Forge/NeoForge 等经过了映射的模组而言，找到能够导入的 jar 依赖库相当困难。有些时候还不如直接修改汇编代码。不过在插件范围内，找到前置库还是相对简单的。</p><h3 id="_04-为什么有些字符串在表格里不显示" tabindex="-1">04. 为什么有些字符串在表格里不显示 <a class="header-anchor" href="#_04-为什么有些字符串在表格里不显示" aria-label="Permalink to &quot;04. 为什么有些字符串在表格里不显示&quot;">​</a></h3><p>这是 Java 的编译机制使然。通常来讲，这些看似无法修改的代码可以比作子类的“投影”，可以在 <code>同名类$xxx</code> 等类似的地方找到。修改后者的字符串后，前者显示的内容会一起改变。</p>',41)),t(i),t(s)])}const q=o(u,[["render",b]]);export{R as __pageData,q as default};
